```bash
cd /home/vscode/nullness-benchmarks/conductor && sed -i '372,375c\    public String getTaskId() {
        if (taskId == null) {
            taskId = java.util.UUID.randomUUID().toString();
        }
        return taskId;
    }' core/src/main/java/com/netflix/conductor/model/TaskModel.java && nl -ba core/src/main/java/com/netflix/conductor/model/TaskModel.java | sed -n '368,382p' && ./gradlew conductor-core:compileJava -x test -q > new_build_output.log 2>&1 || true && grep -n "TaskModel.java" new_build_output.log || true && grep -n "error(s)\? \[NullAway\]" new_build_output.log | tail -n 5 || true
```

